import SwiftUI
import UIKit

// Jarvis Instrument design tokens, shared with the desktop app
// (desktop/src/tokens.css). Semantic names only: views use these, never raw
// colours. Light and dark are tuned separately; each colour follows the
// window's appearance (Settings › Appearance).
//
// The OKLCH values are converted to sRGB once by ios/scripts/instrument_tokens.py
// (OKLab matrices by Björn Ottosson, sRGB transfer curve, 8-bit rounding; every
// value is inside sRGB). Run it with --check to verify this file is current.
enum JV {
    // Generated by ios/scripts/instrument_tokens.py from desktop/src/tokens.css.
    static let bgPage = Color(Token.bgPage)
    static let bgSurface = Color(Token.bgSurface)
    static let bgRaised = Color(Token.bgRaised)
    static let bgSunken = Color(Token.bgSunken)
    static let bgHover = Color(Token.bgHover)
    static let bgSelected = Color(Token.bgSelected)
    static let bgScrim = Color(Token.bgScrim)
    static let borderSubtle = Color(Token.borderSubtle)
    static let border = Color(Token.border)
    static let borderStrong = Color(Token.borderStrong)
    static let separator = Color(Token.separator)
    static let textPrimary = Color(Token.textPrimary)
    static let textSecondary = Color(Token.textSecondary)
    static let textDisabled = Color(Token.textDisabled)
    static let textInverse = Color(Token.textInverse)
    static let textOnAccent = Color(Token.textOnAccent)
    static let accentSubtle = Color(Token.accentSubtle)
    static let accentBorder = Color(Token.accentBorder)
    static let accentSolid = Color(Token.accentSolid)
    static let accentSolidHover = Color(Token.accentSolidHover)
    static let accentText = Color(Token.accentText)
    static let focusRing = Color(Token.focusRing)
    static let positiveSubtle = Color(Token.positiveSubtle)
    static let positiveSolid = Color(Token.positiveSolid)
    static let positiveText = Color(Token.positiveText)
    static let negativeSubtle = Color(Token.negativeSubtle)
    static let negativeSolid = Color(Token.negativeSolid)
    static let negativeText = Color(Token.negativeText)
    static let dangerSubtle = Color(Token.dangerSubtle)
    static let dangerSolid = Color(Token.dangerSolid)
    static let dangerSolidHover = Color(Token.dangerSolidHover)
    static let dangerText = Color(Token.dangerText)
    static let chartAccent = Color(Token.chartAccent)
    static let chartMa = Color(Token.chartMa)

    enum Token: String, CaseIterable {
        case bgPage = "bg-page"
        case bgSurface = "bg-surface"
        case bgRaised = "bg-raised"
        case bgSunken = "bg-sunken"
        case bgHover = "bg-hover"
        case bgSelected = "bg-selected"
        case bgScrim = "bg-scrim"
        case borderSubtle = "border-subtle"
        case border = "border"
        case borderStrong = "border-strong"
        case separator = "separator"
        case textPrimary = "text-primary"
        case textSecondary = "text-secondary"
        case textDisabled = "text-disabled"
        case textInverse = "text-inverse"
        case textOnAccent = "text-on-accent"
        case accentSubtle = "accent-subtle"
        case accentBorder = "accent-border"
        case accentSolid = "accent-solid"
        case accentSolidHover = "accent-solid-hover"
        case accentText = "accent-text"
        case focusRing = "focus-ring"
        case positiveSubtle = "positive-subtle"
        case positiveSolid = "positive-solid"
        case positiveText = "positive-text"
        case negativeSubtle = "negative-subtle"
        case negativeSolid = "negative-solid"
        case negativeText = "negative-text"
        case dangerSubtle = "danger-subtle"
        case dangerSolid = "danger-solid"
        case dangerSolidHover = "danger-solid-hover"
        case dangerText = "danger-text"
        case chartAccent = "chart-accent"
        case chartMa = "chart-ma"

        /// sRGB 0xRRGGBBAA in light and dark.
        var rgba: (light: UInt32, dark: UInt32) {
            switch self {
            case .bgPage: (0xF9FAFCFF, 0x0C0F12FF)
            case .bgSurface: (0xFFFFFFFF, 0x13161AFF)
            case .bgRaised: (0xFFFFFFFF, 0x1C2024FF)
            case .bgSunken: (0xF2F4F6FF, 0x080A0DFF)
            case .bgHover: (0xECEFF2FF, 0x22262AFF)
            case .bgSelected: (0xE3ECF9FF, 0x1C293DFF)
            case .bgScrim: (0x181B1F52, 0x01020299)
            case .borderSubtle: (0xE4E6E9FF, 0x23272BFF)
            case .border: (0xD5D8DBFF, 0x32363BFF)
            case .borderStrong: (0x82878CFF, 0x6D7279FF)
            case .separator: (0xE4E6E9FF, 0x23272BFF)
            case .textPrimary: (0x181B1FFF, 0xEDEFF1FF)
            case .textSecondary: (0x565B62FF, 0xB3B8BEFF)
            case .textDisabled: (0xA1A5AAFF, 0x5F6469FF)
            case .textInverse: (0xFBFCFDFF, 0x13161AFF)
            case .textOnAccent: (0xFFFFFFFF, 0xFFFFFFFF)
            case .accentSubtle: (0xEDF4FFFF, 0x16273FFF)
            case .accentBorder: (0xACC6ECFF, 0x345687FF)
            case .accentSolid: (0x1C65C8FF, 0x3370C7FF)
            case .accentSolidHover: (0x1256B2FF, 0x2460B7FF)
            case .accentText: (0x1659B5FF, 0x92BDFBFF)
            case .focusRing: (0x3D7EDEFF, 0x70A6F5FF)
            case .positiveSubtle: (0xE3F6F6FF, 0x0E2C2CFF)
            case .positiveSolid: (0x0A8282FF, 0x339797FF)
            case .positiveText: (0x046C6CFF, 0x72D0D0FF)
            case .negativeSubtle: (0xFFF0E7FF, 0x3A2312FF)
            case .negativeSolid: (0xC9690CFF, 0xD58042FF)
            case .negativeText: (0x9F5102FF, 0xF5AB77FF)
            case .dangerSubtle: (0xFFEDEBFF, 0x421C18FF)
            case .dangerSolid: (0xC22826FF, 0xC13C36FF)
            case .dangerSolidHover: (0xAC1A1CFF, 0xA82E29FF)
            case .dangerText: (0xB02B27FF, 0xF98F84FF)
            case .chartAccent: (0x1C65C8FF, 0x70A6F5FF)
            case .chartMa: (0x7347AFFF, 0xB699EBFF)
            }
        }
    }
    // End of generated block.

    /// The ring and soft drop of --shadow-border: black 6 % ring and 4 % drop
    /// in light, white 8 % ring and no drop in dark.
    static let shadowRing = Color(light: 0x0000_000F, dark: 0xFFFF_FF14)
    static let shadowDrop = Color(light: 0x0000_000A, dark: 0x0000_0000)

    enum Radius {
        static let sm: CGFloat = 6
        static let md: CGFloat = 10
        static let lg: CGFloat = 14
        static let xl: CGFloat = 20
    }

    /// Durations in seconds (--d-*) and the --ease-out curve.
    enum Motion {
        static let press = 0.15
        static let hover = 0.15
        static let pop = 0.2
        static let modal = 0.24
        static let exit = 0.15
        static let enter = 0.3

        /// cubic-bezier(0.23, 1, 0.32, 1)
        static func easeOut(_ duration: Double) -> Animation {
            .timingCurve(0.23, 1, 0.32, 1, duration: duration)
        }
    }

    // MARK: Type

    enum Weight {
        case regular, medium, semibold

        var sansFace: String {
            switch self {
            case .regular: "IBMPlexSans"
            case .medium: "IBMPlexSans-Medm"
            case .semibold: "IBMPlexSans-SmBld"
            }
        }

        /// Plex Mono ships Regular and Medium here; semibold uses Medium.
        var monoFace: String { self == .regular ? "IBMPlexMono" : "IBMPlexMono-Medm" }

        /// Bold Text: custom faces do not follow it on their own, so every
        /// weight draws as semibold, the heaviest bundled face. It applies
        /// when a view next redraws.
        func legible(bold: Bool) -> Weight { bold ? .semibold : self }

        var system: Font.Weight {
            switch self {
            case .regular: .regular
            case .medium: .medium
            case .semibold: .semibold
            }
        }
    }

    /// IBM Plex Sans, scaled with Dynamic Type relative to `style`.
    static func font(_ size: CGFloat, _ weight: Weight = .regular, relativeTo style: Font.TextStyle = .body) -> Font {
        let weight = weight.legible(bold: UIAccessibility.isBoldTextEnabled)
        return face(weight.sansFace, size, weight, style)
    }

    /// IBM Plex Mono, scaled with Dynamic Type.
    static func mono(_ size: CGFloat, _ weight: Weight = .regular, relativeTo style: Font.TextStyle = .body) -> Font {
        let weight = weight.legible(bold: UIAccessibility.isBoldTextEnabled)
        return face(weight.monoFace, size, weight, style, monospaced: true)
    }

    /// Plex Sans with tabular figures for numbers that change or line up
    /// (Plex digits are already tabular; this also covers the system fallback).
    static func number(_ size: CGFloat, _ weight: Weight = .regular, relativeTo style: Font.TextStyle = .body) -> Font {
        font(size, weight, relativeTo: style).monospacedDigit()
    }

    /// Bundled faces that registered (Info.plist UIAppFonts).
    static let registeredFaces: Set<String> = Set(
        [Weight.regular, .medium, .semibold].flatMap { [$0.sansFace, $0.monoFace] }
            .filter { UIFont(name: $0, size: 12) != nil })

    private static func face(_ name: String, _ size: CGFloat, _ weight: Weight, _ style: Font.TextStyle,
                             monospaced: Bool = false) -> Font {
        let font = Font.custom(name, size: size, relativeTo: style)
        if registeredFaces.contains(name) { return font }
        // A missing face falls back to the system font, still Dynamic Type scaled.
        return monospaced ? font.weight(weight.system).monospaced() : font.weight(weight.system)
    }
}

extension JV.Token {
    /// Resolves to the light or dark value with the trait collection.
    var uiColor: UIColor { UIColor(light: rgba.light, dark: rgba.dark) }
}

extension Color {
    init(_ token: JV.Token) { self.init(uiColor: token.uiColor) }

    /// Dynamic colour from two sRGB 0xRRGGBBAA values.
    init(light: UInt32, dark: UInt32) { self.init(uiColor: UIColor(light: light, dark: dark)) }
}

private extension UIColor {
    convenience init(light: UInt32, dark: UInt32) {
        self.init { $0.userInterfaceStyle == .dark ? UIColor(rgba: dark) : UIColor(rgba: light) }
    }

    convenience init(rgba: UInt32) {
        self.init(red: CGFloat((rgba >> 24) & 0xFF) / 255, green: CGFloat((rgba >> 16) & 0xFF) / 255,
                  blue: CGFloat((rgba >> 8) & 0xFF) / 255, alpha: CGFloat(rgba & 0xFF) / 255)
    }
}

// MARK: - Surfaces

extension View {
    /// Instrument card: surface, 14 pt corners and the hairline border shadow.
    /// `border` replaces the hairline, e.g. for a card that waits on the owner.
    func jvCard(padding: CGFloat = 20, border: Color? = nil) -> some View {
        modifier(CardSurface(padding: padding, border: border))
    }
}

private struct CardSurface: ViewModifier {
    let padding: CGFloat
    let border: Color?
    @Environment(\.colorSchemeContrast) private var contrast

    func body(content: Content) -> some View {
        let shape = RoundedRectangle(cornerRadius: JV.Radius.lg, style: .continuous)
        // Increase Contrast: the faint hairline becomes a 3:1 outline.
        let hairline = contrast == .increased ? JV.borderStrong : JV.shadowRing
        return content.padding(padding)
            .background(JV.bgSurface, in: shape)
            .overlay(shape.strokeBorder(border ?? hairline, lineWidth: 1))
            .shadow(color: JV.shadowDrop, radius: 2, y: 1)
    }
}

// MARK: - Buttons

/// Instrument button: primary, secondary, quiet or danger at 40 (regular),
/// 48 (large) or 32 (small) points; heights grow with Dynamic Type. A
/// destructive role makes primary draw as danger and secondary and quiet labels
/// use the danger colour. Pressing
/// scales to 0.96 over 150 ms ease-out; with Reduce Motion it dims instead.
struct JVButtonStyle: ButtonStyle {
    enum Kind { case primary, secondary, quiet, danger }
    enum Size { case regular, large, small }

    var kind: Kind = .primary
    var size: Size = .regular

    func makeBody(configuration: Configuration) -> some View {
        StyledButton(configuration: configuration, kind: kind, size: size)
    }

    private struct StyledButton: View {
        let configuration: ButtonStyleConfiguration
        let kind: Kind
        let size: Size
        @Environment(\.isEnabled) private var isEnabled
        @Environment(\.accessibilityReduceMotion) private var reduceMotion

        private var metrics: (height: CGFloat, padding: CGFloat, font: CGFloat, radius: CGFloat) {
            switch size {
            case .regular: (40, 16, 14, JV.Radius.md)
            case .large: (48, 20, 15, 12)
            case .small: (32, 12, 13, 8)
            }
        }

        /// A destructive primary button is a danger button.
        private var effectiveKind: Kind {
            kind == .primary && configuration.role == .destructive ? .danger : kind
        }

        private var foreground: Color {
            guard isEnabled else { return JV.textDisabled }
            switch effectiveKind {
            case .primary, .danger: return JV.textOnAccent
            case .secondary: return configuration.role == .destructive ? JV.dangerText : JV.textPrimary
            case .quiet: return configuration.role == .destructive ? JV.dangerText : JV.accentText
            }
        }

        private var background: Color {
            guard isEnabled else { return JV.bgSunken }
            let pressed = configuration.isPressed
            switch effectiveKind {
            case .primary: return pressed ? JV.accentSolidHover : JV.accentSolid
            case .danger: return pressed ? JV.dangerSolidHover : JV.dangerSolid
            case .secondary: return pressed ? JV.bgHover : JV.bgSurface
            case .quiet: return pressed ? JV.bgSelected : JV.accentSubtle
            }
        }

        var body: some View {
            let shape = RoundedRectangle(cornerRadius: metrics.radius, style: .continuous)
            let pressed = configuration.isPressed && isEnabled
            configuration.label
                .font(JV.font(metrics.font, .medium))
                .foregroundStyle(foreground)
                .multilineTextAlignment(.center)
                .padding(.horizontal, metrics.padding)
                .padding(.vertical, 6)
                .frame(minHeight: metrics.height)
                .background(background, in: shape)
                // Secondary and disabled buttons keep a visible outline on a surface card.
                .overlay {
                    if kind == .secondary || !isEnabled { shape.strokeBorder(JV.border, lineWidth: 1) }
                }
                .contentShape(shape)
                .scaleEffect(pressed && !reduceMotion ? 0.96 : 1)
                .opacity(pressed && reduceMotion ? 0.8 : 1)
                .animation(JV.Motion.easeOut(JV.Motion.press), value: pressed)
        }
    }
}

// MARK: - Appearance

/// Light, dark or follow the system; stored on this device only.
enum Appearance: String, CaseIterable, Identifiable {
    case system, light, dark

    static let storageKey = "jarvis.appearance"

    var id: Self { self }

    var label: String {
        switch self {
        case .system: "System"
        case .light: "Light"
        case .dark: "Dark"
        }
    }

    var style: UIUserInterfaceStyle {
        switch self {
        case .system: .unspecified
        case .light: .light
        case .dark: .dark
        }
    }

    /// Applies to every window, so alerts and sheets follow too.
    @MainActor static func apply(_ appearance: Appearance) {
        for case let scene as UIWindowScene in UIApplication.shared.connectedScenes {
            for window in scene.windows { window.overrideUserInterfaceStyle = appearance.style }
        }
    }
}

// MARK: - Status

extension Tone {
    /// Text-safe colour of a status; the label beside it carries the meaning.
    var color: Color {
        switch self {
        case .ok: JV.positiveText
        case .idle: JV.textSecondary
        case .warn: JV.negativeText
        case .error: JV.dangerText
        }
    }
}
